def total(values: list[int]) -> int:
    return sum(values)

payload = "12,7,3"  # donnée mal validée venant d'un formulaire externe
print(total(payload))  # TypeError seulement à l'exécution : Python ne vérifie jamais list[int]

# $ mypy service.py
# error: Argument 1 to "total" has incompatible type "str"; expected "list[int]"

